  ".then(function(r){return r.json()}).then(function(d){",
  'if(!d.ok){msg("\u062E\u0637\u0627: "+(d.error||"\u0646\u0627\u0645\u0634\u062E\u0635"),"#f0596b");b.textContent=origTxt;b.disabled=false;return}',
