// server/walletBot.js
var COINS = [
  { id: "BTC", symbol: "BTC/USD", token: "cbBTC", name: "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646" },
  { id: "ETH", symbol: "ETH/USD", token: "WETH", name: "\u0627\u062A\u0631\u06CC\u0648\u0645" }
];
var PARAMS = { lookback: 20, volMult: 2, atrPeriod: 14, trailAtr: 6, gatePeriod: 50 };
var OMEGA = { minScore: 60, tf: "1h", tpPct: 3, slPct: 0.65, maxHoldBars: 48 };
var DEFAULT = {
  enabled: false,
  live: false,
  allocPct: 50,
  // درصد موجودی USDC برای هر پوزیشن
  maxPositions: 2,
  slippagePct: 1,
  minScore: 60,
  strategy: "trend",
  // 'trend' = روند روزانه (بک‌تست‌شده) · 'omega' = امتیازدهی موتور داشبورد
  lastBarTime: 0,
  lastScanAt: 0,
  lastScore: null
};
function store() {
  const s = tradingEngine.state;
  if (!s.nexusWallet || typeof s.nexusWallet !== "object") {
    s.nexusWallet = { bot: { ...DEFAULT }, positions: {}, log: [] };
  }
  const w = s.nexusWallet;
  if (!w.bot) w.bot = { ...DEFAULT };
  if (!w.positions) w.positions = {};
  if (!Array.isArray(w.log)) w.log = [];
  w.bot = { ...DEFAULT, ...w.bot };
  return w;
}
var save2 = () => {
  try {
    tradingEngine.saveState();
  } catch {
  }
};
function sma(a, p) {
  const out = new Array(a.length).fill(null);
  let s = 0;
  for (let i = 0; i < a.length; i++) {
    s += a[i];
    if (i >= p) s -= a[i - p];
    if (i >= p - 1) out[i] = s / p;
  }
  return out;
}
function atrSeries(bars, p = 14) {
  const out = new Array(bars.length).fill(null);
  const tr = bars.map(
    (b2, i) => i === 0 ? b2.high - b2.low : Math.max(b2.high - b2.low, Math.abs(b2.high - bars[i - 1].close), Math.abs(b2.low - bars[i - 1].close))
  );
  let prev = null;
  for (let i = 0; i < bars.length; i++) {
    if (i === p - 1) {
      let s = 0;
      for (let j = 0; j < p; j++) s += tr[j];
      prev = s / p;
      out[i] = prev;
    } else if (i >= p) {
      prev = (prev * (p - 1) + tr[i]) / p;
      out[i] = prev;
    }
  }
  return out;
}
var sameDay = (sec, now) => new Date(sec * 1e3).toISOString().slice(0, 10) === new Date(now).toISOString().slice(0, 10);
function lastCompleted(bars) {
  let i = bars.length - 1;
  while (i > 0 && sameDay(bars[i].time, Date.now())) i--;
  return i;
}
async function scanOmega(w, cfg) {
  const actions = [];
  const errors = [];
  const scores = {};
  const bal = await getBalances().catch(() => null);
  const prices = await getPrices().catch(() => ({}));
  for (const coin of COINS) {
    try {
      const { candles } = await marketService.getCandles(coin.symbol, OMEGA.tf);
      if (!candles || candles.length < 60) {
        errors.push(`${coin.id}: \u06A9\u0646\u062F\u0644 \u06A9\u0627\u0641\u06CC \u0646\u06CC\u0633\u062A`);
        continue;
      }
      const bars = candles.slice(0, -1);
      const bar = bars[bars.length - 1];
      const a = computeFullAnalysis(bars);
      const score = a?.summary?.score ?? 0;
      const analysisSignal = a?.summary?.signal || "NEUTRAL";
      scores[coin.id] = score;
      w.bot.lastSignal = { ...w.bot.lastSignal || {}, [coin.id]: analysisSignal };
      const price = bar.close;
      const pos = w.positions[coin.id];
      if (pos) {
        const pnlPct = (price / pos.entryPrice - 1) * 100;
        const held = Date.now() - (pos.entryAt || Date.now());
        const reason = pnlPct >= OMEGA.tpPct ? `\u062D\u062F \u0633\u0648\u062F ${OMEGA.tpPct}%` : pnlPct <= -OMEGA.slPct ? `\u062D\u062F \u0636\u0631\u0631 ${OMEGA.slPct}%` : score <= -20 ? "\u0628\u0631\u06AF\u0634\u062A \u0627\u0645\u062A\u06CC\u0627\u0632 \u0628\u0647 \u0645\u0646\u0641\u06CC" : held > OMEGA.maxHoldBars * 36e5 ? "\u0627\u062A\u0645\u0627\u0645 \u0632\u0645\u0627\u0646 \u0646\u06AF\u0647\u200C\u062F\u0627\u0631\u06CC" : null;
        if (reason) {
          let exec2 = null;
          try {
            exec2 = await swap({
              tokenIn: coin.token,
              tokenOut: "USDC",
              amountIn: pos.qty,
              slippagePct: cfg.slippagePct,
              live: Boolean(cfg.live),
              note: `\u0627\u0645\u06AF\u0627: ${reason}`
            });
          } catch (e) {
            errors.push(`${coin.id} \u0641\u0631\u0648\u0634: ${e.message}`);
          }
          delete w.positions[coin.id];
          w.log.push({
            id: `${coin.id}-${Date.now()}`,
            coin: coin.id,
            side: "SELL",
            price,
            qty: pos.qty,
            usd: price * pos.qty,
            pnlPct,
            simulated: !cfg.live,
            at: Date.now(),
            hash: exec2?.hash || null,
            note: `\u0627\u0645\u06AF\u0627: ${reason}`
          });
          actions.push({ coin: coin.id, action: "SELL", reason, exec: exec2?.hash || (cfg.live ? "\u062E\u0637\u0627" : "\u0634\u0628\u06CC\u0647\u200C\u0633\u0627\u0632\u06CC") });
        }
        continue;
      }
      const threshold = Number.isFinite(Number(cfg.minScore)) ? Number(cfg.minScore) : OMEGA.minScore;
      if (score < threshold) {
        actions.push({ coin: coin.id, action: "WAIT", reason: `\u0627\u0645\u062A\u06CC\u0627\u0632 ${score} < ${threshold}` });
        continue;
      }
      if (Object.keys(w.positions).length >= (cfg.maxPositions || 2)) {
        actions.push({ coin: coin.id, action: "SKIP", reason: "\u0633\u0642\u0641 \u067E\u0648\u0632\u06CC\u0634\u0646 \u067E\u0631 \u0627\u0633\u062A" });
        continue;
      }
      const usdc = bal?.usdc || 0;
      const spend = Math.min(usdc * cfg.allocPct / 100, walletStatus().maxTradeUsd);
      if (spend < 1) {
        actions.push({ coin: coin.id, action: "SKIP", reason: `USDC \u06A9\u0645 \u0627\u0633\u062A ($${usdc.toFixed(2)})` });
        continue;
      }
      let exec = null;
      try {
        exec = await swap({
          tokenIn: "USDC",
          tokenOut: coin.token,
          amountIn: spend,
          slippagePct: cfg.slippagePct,
          live: Boolean(cfg.live),
          note: `\u0627\u0645\u06AF\u0627: \u0627\u0645\u062A\u06CC\u0627\u0632 ${score}`
        });
      } catch (e) {
        errors.push(`${coin.id} \u062E\u0631\u06CC\u062F: ${e.message}`);
        actions.push({ coin: coin.id, action: "SKIP", reason: e.message });
        continue;
      }
      const qty = exec?.plan?.quoteOut || 0;
      w.positions[coin.id] = {
        id: coin.id,
        token: coin.token,
        qty,
        entryPrice: price,
        entryAt: Date.now(),
        highWater: price,
        usdIn: spend,
        live: Boolean(cfg.live),
        strategy: "omega"
      };
      w.log.push({
        id: `${coin.id}-${Date.now()}`,
        coin: coin.id,
        side: "BUY",
        price,
        qty,
        usd: spend,
        simulated: !cfg.live,
        at: Date.now(),
        hash: exec?.hash || null,
        note: `\u0627\u0645\u06AF\u0627: \u0627\u0645\u062A\u06CC\u0627\u0632 ${score}`
      });
      actions.push({ coin: coin.id, action: "BUY", reason: `\u0627\u0645\u062A\u06CC\u0627\u0632 ${score}`, exec: exec?.hash || (cfg.live ? "\u062E\u0637\u0627" : "\u0634\u0628\u06CC\u0647\u200C\u0633\u0627\u0632\u06CC") });
    } catch (e) {
      errors.push(`${coin.id}: ${e.message}`);
    }
  }
  w.bot.lastScore = scores;
  return { actions, errors, scores, strategy: "omega" };
}
async function scan2({ force = false } = {}) {
  const w = store();
  const cfg = w.bot;
  const result = { at: Date.now(), gate: null, actions: [], errors: [], skipped: false };
  const btc = await marketService.getCandles("BTC/USD", "1d");
  const btcBars = btc.candles;
  const bi = lastCompleted(btcBars);
  const btcCloses = btcBars.map((b2) => b2.close);
  const ma = sma(btcCloses, PARAMS.gatePeriod)[bi];
  const gateOpen = ma != null && btcBars[bi].close > ma;
  result.gate = { open: gateOpen, price: btcBars[bi].close, ma, source: btc.source };
  w.bot.lastGate = result.gate;
  if (cfg.enabled && cfg.strategy === "omega") {
    const out = await scanOmega(w, cfg);
    w.bot.lastScanAt = Date.now();
    save2();
    return { ...result, ...out, gate: result.gate };
  }
  const barTime = btcBars[bi].time;
  if (!force && cfg.lastBarTime === barTime && !result.actions.length) {
    result.skipped = true;
    result.note = "\u06A9\u0646\u062F\u0644 \u062C\u062F\u06CC\u062F\u06CC \u0627\u0632 \u0622\u062E\u0631\u06CC\u0646 \u0627\u0633\u06A9\u0646 \u0646\u06CC\u0627\u0645\u062F\u0647";
  }
  if (cfg.enabled) {
    const bal = await getBalances().catch(() => null);
    const prices = await getPrices().catch(() => ({}));
    for (const coin of COINS) {
      try {
        const { candles } = await marketService.getCandles(coin.symbol, "1d");
        const idx = lastCompleted(candles);
        if (idx < 40) continue;
        const bar = candles[idx];
        const prev = candles.slice(idx - PARAMS.lookback, idx);
        const rangeHigh = Math.max(...prev.map((b2) => b2.high));
        const volAvg = prev.reduce((s, b2) => s + b2.volume, 0) / prev.length;
        const volRatio = volAvg > 0 ? bar.volume / volAvg : 0;
        const atr = atrSeries(candles)[idx];
        const pos = w.positions[coin.id];
        if (pos) {
          const hw = Math.max(pos.highWater || pos.entryPrice, bar.high);
          pos.highWater = hw;
          const trailLevel = hw - PARAMS.trailAtr * (pos.atrAtEntry || atr || 0);
          const reason = !gateOpen ? "\u06AF\u06CC\u062A \u0628\u0627\u0632\u0627\u0631 \u0628\u0633\u062A\u0647 \u0634\u062F" : bar.close < trailLevel ? "\u062A\u0631\u06CC\u0644\u06CC\u0646\u06AF \u0627\u0633\u062A\u0627\u067E" : null;
          if (reason) {
            const qty = pos.qty;
            let exec = null;
            try {
              exec = await swap({
                tokenIn: coin.token,
                tokenOut: "USDC",
                amountIn: qty,
                slippagePct: cfg.slippagePct,
                live: Boolean(cfg.live),
                note: reason
              });
              if (!cfg.live || exec.ok) {
                w.log.push({
                  id: `${coin.id}-out-${Date.now()}`,
                  coin: coin.id,
                  side: "SELL",
                  reason,
                  price: bar.close,
                  qty,
                  usd: qty * (prices[coin.token] || bar.close),
                  at: Date.now(),
                  live: Boolean(cfg.live),
                  hash: exec?.hash || null,
                  simulated: Boolean(exec?.simulated)
                });
                delete w.positions[coin.id];
              }
            } catch (e) {
              result.errors.push(`${coin.id} SELL: ${e.message}`);
            }
            result.actions.push({ coin: coin.id, action: "SELL", reason, exec: exec?.message || null });
          }
          continue;
        }
        if (!gateOpen) continue;
        if (bar.close > rangeHigh && volRatio >= PARAMS.volMult) {
          if (Object.keys(w.positions).length >= cfg.maxPositions) {
            result.actions.push({ coin: coin.id, action: "SKIP", reason: "\u0633\u0642\u0641 \u067E\u0648\u0632\u06CC\u0634\u0646 \u067E\u0631 \u0627\u0633\u062A" });
            continue;
          }
          const usdc = bal?.usdc || 0;
          const spend = Math.min(usdc * cfg.allocPct / 100, walletStatus().maxTradeUsd);
          if (spend < 1) {
            result.actions.push({ coin: coin.id, action: "SKIP", reason: `\u0645\u0648\u062C\u0648\u062F\u06CC USDC \u06A9\u0645 \u0627\u0633\u062A ($${usdc.toFixed(2)})` });
            continue;
          }
          const exec = await swap({
            tokenIn: "USDC",
            tokenOut: coin.token,
            amountIn: spend,
            slippagePct: cfg.slippagePct,
            live: Boolean(cfg.live),
            note: `\u0634\u06A9\u0633\u062A \u0633\u0642\u0641 \u06F2\u06F0 \u0631\u0648\u0632\u0647 \u0628\u0627 \u062D\u062C\u0645 ${volRatio.toFixed(1)}\xD7`
          });
          const gotQty = exec?.plan?.quoteOut || 0;
          w.positions[coin.id] = {
            id: coin.id,
            token: coin.token,
            qty: gotQty,
            entryPrice: bar.close,
            entryAt: Date.now(),
            highWater: bar.close,
            atrAtEntry: atr,
            usdIn: spend,
            live: Boolean(cfg.live)
          };
          w.log.push({
            id: `${coin.id}-${Date.now()}`,
            coin: coin.id,
            side: "BUY",
            price: bar.close,
            qty: gotQty,
            usd: spend,
            volRatio,
            at: Date.now(),
            live: Boolean(cfg.live),
            hash: exec?.hash || null,
            simulated: Boolean(exec?.simulated)
          });
          result.actions.push({ coin: coin.id, action: "BUY", usd: spend, exec: exec?.message || null });
        }
      } catch (e) {
        result.errors.push(`${coin.id}: ${e.message}`);
      }
    }
    cfg.lastBarTime = barTime;
  }
  cfg.lastScanAt = Date.now();
  save2();
  return result;
}
async function getState() {
  const w = store();
  const st = walletStatus();
  const [bal, prices] = await Promise.all([
    getBalances().catch(() => null),
    getPrices().catch(() => ({}))
  ]);
  const positions = Object.values(w.positions).map((p) => {
    const price = prices[p.token] || null;
    return {
      ...p,
      price,
      pnlPct: price ? (price / p.entryPrice - 1) * 100 : null,
      valueUsd: price ? price * p.qty : null
    };
  });
  const closed = w.log.filter((x) => x.side === "SELL");
  const opens = w.log.filter((x) => x.side === "BUY");
  let wins = 0;
  for (const s of closed) {
    const b2 = opens.find((o) => o.coin === s.coin && o.at < s.at);
    if (b2 && s.price > b2.price) wins++;
  }
  return {
    ok: true,
    wallet: st,
    balances: bal,
    prices,
    positions,
    bot: w.bot,
    log: w.log.slice(-40).reverse(),
    stats: {
      buys: opens.length,
      sells: closed.length,
      winRate: closed.length ? wins / closed.length * 100 : 0,
      simulated: w.log.filter((x) => x.simulated).length,
      live: w.log.filter((x) => x.live && !x.simulated).length
    },
    params: PARAMS,
    coins: COINS.map((c) => ({ id: c.id, token: c.token, name: c.name, price: prices[c.token] || null }))
  };
}
function setBot(patch = {}) {
  const w = store();
  const b2 = w.bot;
  if (patch.enabled != null) b2.enabled = Boolean(patch.enabled);
  if (patch.live != null) b2.live = Boolean(patch.live);
  if (patch.allocPct != null) b2.allocPct = Math.min(100, Math.max(1, Number(patch.allocPct) || 50));
  if (patch.maxPositions != null) b2.maxPositions = Math.min(2, Math.max(1, Number(patch.maxPositions) || 2));
  if (patch.slippagePct != null) b2.slippagePct = Math.min(5, Math.max(0.2, Number(patch.slippagePct) || 1));
  if (patch.minScore != null) b2.minScore = Math.min(100, Math.max(-100, Number(patch.minScore) || 60));
  if (patch.strategy != null) {
    const v = String(patch.strategy);
    b2.strategy = v === "omega" ? "omega" : "trend";
  }
  if (patch.live === true && !b2.enabled) b2.enabled = true;
  save2();
  return b2;
}
function resetLog() {
  const w = store();
  w.log = [];
  w.positions = {};
  save2();
  return { ok: true };
}

