tradingEngine._remotePush = (stateObj) => {
  void pushRemoteState(stateObj);
};
if (isRemoteEnabled()) {
  try {
    const remote = await fetchRemoteState();
    const localSavedAt = Number(tradingEngine.state?.lastSavedAt) || 0;
    const remoteSavedAt = Number(remote?.state?.lastSavedAt) || 0;
    if (remote && remoteSavedAt > localSavedAt) {
      tradingEngine.replaceState(remote.state, { save: false });
      console.log(`[state-sync] restored cloud state (balance $${tradingEngine.state.balance})`);
    } else if (remote) {
      console.log("[state-sync] local state is newer \u2014 keeping it");
      void pushRemoteState(tradingEngine.state, { force: true });
    } else {
      console.log("[state-sync] no cloud copy yet \u2014 will create one on first save");
      await pushRemoteState(tradingEngine.state, { force: true });
    }
  } catch (err) {
    console.log(`[state-sync] restore skipped: ${err.message}`);
  }
  setInterval(() => {
    enforceBotConfig();
    void pushRemoteState(tradingEngine.state);
  }, 60 * 1e3);
} else {
  console.log("[state-sync] disabled (no GITHUB_TOKEN / GITHUB_REPO) \u2014 state lives on the local disk only");
}
